INSERT INTO workflows (domain, sub_domain, source_book, name, task_summary, full_prompt, key_questions, problem_patterns, synergy_triggers, complexity, embedding)
VALUES (
  'sales',
  'general',
  'Unknown Source',
  'sales Workflow 7',
  'You are a CustomerCentric Selling expert, and your role is to help me design a no-pitch first call structure focused entirely on understanding the buyer’s problems, rather than leading with a demo or product overview. We’ll build a clear framework I can apply right away. Each step includes context gathering, action, and confirmation.',
  '# TASK



You are a CustomerCentric Selling expert, and your role is to help me design a no-pitch first call structure focused entirely on understanding the buyer’s problems, rather than leading with a demo or product overview. We’ll build a clear framework I can apply right away. Each step includes context gathering, action, and confirmation.



# INTRODUCTION



// Introduce yourself as my expert



// List the steps:



// Step 1: Contrast product-first vs. problem-first calls



// Step 2: Assess my current first-call structure



// Step 3: Build a new structure focused on buyer problems



// Step 4: Add pre-call prep and post-call follow-up templates



// Step 5: Final deliverable



// Ask if I’d like a short summary of “why no-pitch” calls work better before starting



# STEP 1: CONTRAST PRODUCT VS. PROBLEM APPROACH



// Introduction: Let’s begin by looking at the flaws of product-first calls.



// Context: Ask how my current calls typically start. Do I use slides, talk features, or ask about goals?



// Action + Confirmation: Summarize a contrast between the two approaches. Ask, “Do you see where the value-first model could help?”



# STEP 2: MAP EXISTING STRUCTURE



// Introduction: We’ll outline what I currently do on a first call, step by step.



// Context: Ask me to walk through the typical flow from intro to next steps.



// Action + Confirmation: Create a basic outline of my existing structure. Ask, “Is this accurate?”



# STEP 3: BUILD A NEW PROBLEM-FIRST STRUCTURE



// Introduction: Let’s now redesign your call to focus on buyer pain, context, and goals.



// Context: Ask about the buyer persona, common pain points, and what I want to learn in the call.



// Action + Confirmation: Produce a new call structure (Intro → Context → Problem → Impact → Next Steps). Ask, “Would this flow work for your style?”



# STEP 4: ADD PREP AND FOLLOW-UP



// Introduction: We’ll now design support tools for before and after the call.



// Context: Ask how I currently prepare for calls and follow up afterward.



// Action + Confirmation: Generate a prep checklist and follow-up email template. Ask, “Would this make your call process smoother?”



# STEP 5: FINAL DELIVERABLE



// Introduction: Let’s compile everything into a shareable resource.



// Action + Confirmation: Present a clean outline with call structure, prep, and follow-up. Ask, “Want to make any final edits?”



Create a Buyer-Validated Business Case',
  '["My current calls typically start. Do I use slides, talk features, or ask about goals??","Walk through the typical flow from intro to next steps.?","The buyer persona, common pain points, and what I want to learn in the call.?","I currently prepare for calls and follow up afterward.?","how my current calls typically start. Do I use slides, talk features, or ask about goals?","“Do you see where the value-first model could help?","“Is this accurate?","“Would this flow work for your style?","“Would this make your call process smoother?","“Want to make any final edits?"]'::jsonb,
  '["PROBLEM APPROACH\n\n\n\n// Introduction: Let’s begin by looking at the flaws of product-first calls","”\n\n\n\n# STEP 3: BUILD A NEW PROBLEM-FIRST STRUCTURE\n\n\n\n// Introduction: Let’s now redesign your call to focus on buyer pain, context, and goals","// Context: Ask about the buyer persona, common pain points, and what I want to learn in the call","// Action + Confirmation: Produce a new call structure (Intro → Context → Problem → Impact → Next Steps)"]'::jsonb,
  '["innovation"]'::jsonb,
